mapper.select:
select v.id, v.user_id, v.name, v.phone, v.apartment_id, v.appointment_time, v.additional_info, v.appointment_status, v.room_id, ri.room_number, ai.id apartment_id, ai.name apartment_name, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name
from lease.view_appointment v left join lease.apartment_info ai on v.apartment_id = ai.id and ai.is_deleted = 0 left join lease.room_info ri on ri.id=v.room_id and ri.is_deleted=0
v.is_deleted=0
and ai.province_id=#{queryVo.provinceId}
and ai.city_id = #{queryVo.cityId}
and ai.district_id = #{queryVo.districtId}
and v.apartment_id = #{queryVo.apartmentId}
and v.name like concat('%',#{queryVo.name},'%')
and v.phone like concat('%',#{queryVo.phone},'%')
